export const DONNELLY_1882_EVIDENCE =
  "Atlantis: The Antediluvian World, by Ignatius Donnelly (New York: Harper & Brothers, 1882), the 1882 setting; public domain (published in the United States in 1882; Donnelly died in 1901). Taken from Project Gutenberg #4032 and compared word by word with the archive.org OCRs of four printed copies of the 1882 setting: the Duke University copy, 'Eleventh Edition' (atlantisantedil00donn), two other 'Eleventh Edition' copies (atlantisantedilu0000unse, Atlantis1882) and the 'Twenty-fourth Edition' of 1904 (atlantisantedilu0000igna_s0m2); where at least three witnesses outvote the transcription their reading is taken. Twelve readings were taken by the vote (among them 'hearing' for 'bearing', 'Hea' for 'Idea', Jowett's volume ii p. '517', and a phrase of Critias 116c restored to its place) and seven places corrected by hand (Oppert's two tables, given from the print, 'judgment', a dash and three capital letters), read on the Duke page images (pp. 3, 5, 20, 29, 30, 65, 67, 283). No copy of the very first printing was reached. Punctuation is not voted. All are listed in scripts/texts/atlantis-authors.py. Italic and small capitals are not marked.";

function englishLayer(chapter: DonnellyChapter): CorpusLayer {
  return {
    key: "eng-1882",
    layer: "primary_text",
    sourceKey: SOURCE,
    content: chapter.text,
    language: "English",
    licence: "public_domain",
    evidence: `${DONNELLY_1882_EVIDENCE} (Part ${chapter.part}, chapter ${chapter.chapter}, pp. ${chapter.firstPage}–${chapter.lastPage})`,
  };
}

