function chapterPassage(chapter: DonnellyChapter): CorpusPassage {
  const meta = CHAPTERS[chapter.id];
  const key = `${BOOK}.${chapter.id}`;
  return {
    key,
    parentKey: BOOK,
    divisionKind: "chapter",
    label: meta.label,
    reference: `Atlantis: The Antediluvian World (New York, 1882), Part ${chapter.part}, chapter ${chapter.chapter}, '${chapter.title}', pp. ${chapter.firstPage}–${chapter.lastPage}`,
    sourceKey: SOURCE,
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [englishLayer(chapter)],
    themes: meta.themes.map(([themeKey, note]) => ({ themeKey, note })),
    images: imagesFor(DONNELLY_IMAGES, key),
  };
}

