const NOT_A_WITNESS =
  "Donnelly's Atlantis is a book of 1882, not a witness to the earlier text: it quotes Plato in Jowett's English and reads the story as literal history, a reading the dialogues do not support and geology rejects.";

type PlatoQuote = { key: string; from: string; to: string; similarities: string; differences: string; evidence?: string };

function platoLink(q: PlatoQuote): CorpusLink {
  const dialogue = q.to.startsWith("greek.tim.") ? "Timaeus" : "Critias";
  return {
    key: q.key,
    from: `${BOOK}.${q.from}`,
    to: q.to,
    connectionClass: "later_reinterpretation",
    similarities: q.similarities,
    differences: q.differences,
    wordingComparable: "partly",
    meaningComparable: "yes",
    transmissionEvidence: `${q.evidence ?? `He names Plato and quotes the ${dialogue} in Jowett's English.`} ${NOT_A_WITNESS}`,
    earlierNote: `The ${dialogue} was written in the fourth century BCE.`,
    reviewStatus: "proposed",
  };
}

